pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testRegression_property() public {
        address owner = address(0x1);
        address user1 = address(0x2);
        vm.prank(owner);
        c.approveMax();
        vm.deal(user1, 1 ether);
        vm.prank(user1);
        c.supplyTokenTo(100, user1);
        uint256 balanceBefore = c.imBalances(user1);
        vm.prank(user1);
        c.redeemToken(100);
        uint256 balanceAfter = c.imBalances(user1);
        assertTrue(balanceAfter < balanceBefore);
    }
}

