import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0); }
    function testRegression_property() public {
        // Deploy a mock savings contract to make c functional
        // Since the reference contract already approves max in constructor,
        // calling approveMax again from a non-owner must revert on reference.
        // The buggy version removes onlyOwner so it succeeds.
        address nonOwner = address(0x1234);
        vm.prank(nonOwner);
        // Reference: reverts because nonOwner is not owner
        // Bug: succeeds (no modifier)
        bool ok;
        try c.approveMax() {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract should revert (ok == false)
        // The buggy contract would not revert (ok == true)
        assertTrue(!ok, "Reference reverts; bug succeeds");
    }
}

