    C c;
    function setUp() public { c = new C(ISavingsContractV2(0)); }
    function testRegression_property() public {
        // Call approveMax() to trigger the depositToken() difference
        c.approveMax();
        // Assert that depositToken() returns a non-zero address (the mAsset)
