interface ISavingsContractV2 {
    function underlying() external view returns (IERC20);
    function exchangeRate() external view returns (uint256);
    function depositSavings(uint256 amount) external returns (uint256);
    function depositSavings(uint256 amount, address beneficiary) external returns (uint256);
    function redeemUnderlying(uint256 amount) external returns (uint256);
    function creditBalances(address) external view returns (uint256);
    function depositInterest(uint256 amount) external;
    function redeemCredits(uint256 amount) external returns (uint256);
    function redeemUnderlying(uint256) external returns (uint256);
    function balanceOfUnderlying(address user) external view returns (uint256);
    function underlyingToCredits(uint256 underlying) external view returns (uint256);
    function creditsToUnderlying(uint256 credits) external view returns (uint256);
}

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

